#pragma once

#include "monstres/render/renderer.hpp"

#include <cstddef>
#include <vector>

namespace monstres {

// Every mesh of the game, generated by code in a low-poly, flat-shaded style.
// Each mesh has its origin at the center of its base (on the ground), except
// the cube and the crate, which are centered.
//
// Unit sizes, scaled per object by the scene (see scene.cpp):
//   Tree, Pine   a full tree for scale 1 (about 4.4 m high)
//   Rock*        fits [-1, 1] x [0, 1] x [-1, 1]
//   Log          along X, fits [-1, 1] x [0, 2] x [-1, 1] (radius 1)
//   Stump, Bush  fit [-1, 1] x [0, 1] x [-1, 1]
//   Crate, Cube  fit [-1, 1]^3
enum class MeshId : size_t {
  Cube,
  Tree,
  Pine,
  Rock0, Rock1, Rock2, Rock3,
  Log,
  Stump,
  Bush,
  Crate,
  Count
};
inline constexpr size_t kMeshCount = static_cast<size_t>(MeshId::Count);
inline constexpr size_t kRockVariants = 4;

// All meshes, indexed by MeshId.
std::vector<MeshData> build_meshes();

}  // namespace monstres
